void app_main()
{
    // Initialize NVS
    esp_err_t ret = nvs_flash_init();
    if (ret == ESP_ERR_NVS_NO_FREE_PAGES || ret == ESP_ERR_NVS_NEW_VERSION_FOUND) {
        ESP_ERROR_CHECK(nvs_flash_erase());
        ret = nvs_flash_init();
    }
    ESP_ERROR_CHECK( ret );
	ESP_ERROR_CHECK(esp_event_loop_create_default());


	//Enable initial stop condition
	dbg_mode = 0x08;

	ICD_PUSH(0);


  FC_MARKER(6);

#if 0 // Disabled code
  // Interrupt, Type: Interrupt: Enable TMR1
  FC_CAL_Timer_Period = 5;
  FC_CAL_Timer_Multiplier = 1;
  FC_CAL_Timer_Init(1, FC_CAL_Timer_Period * FC_CAL_Timer_Multiplier, FC_CAL_Timer_1_ISR);

#endif // Disabled code

  FC_MARKER(11);

  // Loop, Type: Loop: While 1
  while (1)
  {
    FC_MARKER(11);

    if ((1) == 0) break;
    FC_MARKER(8);

    // Calculation, Type: Calculation:
    // count = count + 1
    FCV_COUNT = FCV_COUNT + 1;

    FC_MARKER(9);

    // Output, Type: Output: count & 1 -> GPIO22
    SET_PORT_PIN(A,22,(FCV_COUNT & 1));

#if 0 // Disabled code
    // User Macro, Type: User Macro: NewMacro()
    FCM_NewMacro();

#endif // Disabled code

    FC_MARKER(10);

    // Delay, Type: Delay: 100 ms
    FCI_DELAYBYTE_MS(100);

    FC_MARKER(7);

  }

  FC_MARKER(12);

	ICD_POP();

	//Code to signal end of program to ICD
	dbg_mode = 0x08;

	FC_MARKER(-1);


	mainendloop: goto mainendloop;
}

